//! The runtime library of applications generated by Clarity. Generated
//! code describes records and calls into this crate to store them in
//! SQLite, apply migrations and check contracts. It is written by hand once
//! and copied into every generated project, so a project builds on its own.

pub mod query;
pub mod sql;
pub mod ui;

use std::fmt;
use std::path::Path;

pub use chrono::{NaiveDate, NaiveDateTime};
pub use query::{Cond, Op, Query, contains};
pub use rusqlite::types::Value as SqlValue;
pub use rust_decimal::Decimal;

/// The key of a stored record; 0 until it is saved for the first time.
pub type Id = i64;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// A `require` or `ensure` of a function or action did not hold.
    Contract(String),
    /// A record that should exist does not.
    NotFound { table: &'static str, id: Option<Id> },
    /// Another record refers to the record being deleted.
    InUse { table: &'static str, id: Id },
    /// A stored value does not fit its field.
    Invalid(String),
    Storage(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Contract(what) => write!(f, "condition failed: {what}"),
            Error::NotFound { table, id: Some(id) } => write!(f, "there is no {table} with id {id}"),
            Error::NotFound { table, id: None } => write!(f, "no {table} is set"),
            Error::InUse { table, id } => write!(f, "the {table} with id {id} is still referred to"),
            Error::Invalid(what) => write!(f, "invalid value: {what}"),
            Error::Storage(what) => write!(f, "storage: {what}"),
        }
    }
}

impl std::error::Error for Error {}

impl From<rusqlite::Error> for Error {
    fn from(err: rusqlite::Error) -> Self {
        Error::Storage(err.to_string())
    }
}

pub type Result<T> = std::result::Result<T, Error>;

/// Checks a `require` line of a function or action.
pub fn require(holds: bool, what: &str) -> Result<()> {
    if holds { Ok(()) } else { Err(Error::Contract(what.to_string())) }
}

/// Checks an `ensure` line of a function or action.
pub fn ensure(holds: bool, what: &str) -> Result<()> {
    require(holds, what)
}

/// A record of an entity, as generated code describes it.
pub trait Record: Sized + Clone {
    /// The table the records are stored in.
    const TABLE: &'static str;
    /// The stored columns, without `id`, in the order of `to_values`.
    const COLUMNS: &'static [&'static str];
    fn id(&self) -> Id;
    fn set_id(&mut self, id: Id);
    fn to_values(&self) -> Vec<SqlValue>;
    /// Builds a record from values in `COLUMNS` order.
    fn from_values(id: Id, values: &[SqlValue]) -> Result<Self>;
}

/// How a value appears in text, for messages and `"text" + value`.
pub trait Show {
    fn show(&self) -> String;
}

impl Show for String {
    fn show(&self) -> String {
        self.clone()
    }
}

impl Show for &str {
    fn show(&self) -> String {
        (*self).to_string()
    }
}

impl Show for i64 {
    fn show(&self) -> String {
        self.to_string()
    }
}

impl Show for Decimal {
    fn show(&self) -> String {
        self.to_string()
    }
}

impl Show for bool {
    fn show(&self) -> String {
        if *self { "yes".into() } else { "no".into() }
    }
}

impl Show for Option<NaiveDate> {
    fn show(&self) -> String {
        self.map(|d| d.to_string()).unwrap_or_default()
    }
}

impl Show for Option<NaiveDateTime> {
    fn show(&self) -> String {
        self.map(|d| d.format("%Y-%m-%d %H:%M").to_string()).unwrap_or_default()
    }
}

/// The database of an application: one SQLite file.
pub struct Db {
    conn: rusqlite::Connection,
}

impl Db {
    pub fn open(path: &Path) -> Result<Db> {
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|err| Error::Storage(err.to_string()))?;
        }
        Ok(Db {
            conn: rusqlite::Connection::open(path)?,
        })
    }

    /// A database that lives in memory, for tests.
    pub fn memory() -> Result<Db> {
        Ok(Db {
            conn: rusqlite::Connection::open_in_memory()?,
        })
    }

    /// The number of migration steps applied so far.
    pub fn schema_version(&self) -> Result<usize> {
        self.conn
            .execute_batch("CREATE TABLE IF NOT EXISTS clarity_schema (version INTEGER NOT NULL)")?;
        let version: Option<i64> =
            self.conn.query_row("SELECT MAX(version) FROM clarity_schema", [], |row| row.get(0))?;
        Ok(version.unwrap_or(0) as usize)
    }

    /// Applies the steps that are not applied yet, each in a transaction.
    pub fn migrate(&mut self, steps: &[&str]) -> Result<usize> {
        let done = self.schema_version()?;
        for (i, step) in steps.iter().enumerate().skip(done) {
            let tx = self.conn.transaction()?;
            tx.execute_batch(step)?;
            tx.execute("INSERT INTO clarity_schema (version) VALUES (?1)", [i as i64 + 1])?;
            tx.commit()?;
        }
        Ok(steps.len().saturating_sub(done))
    }

    /// Inserts a new record (and gives it its id) or updates a stored one.
    pub fn save<R: Record>(&self, record: &mut R) -> Result<()> {
        let values = record.to_values();
        if record.id() == 0 {
            let columns = R::COLUMNS.iter().map(|c| quoted(c)).collect::<Vec<_>>().join(", ");
            let marks = (1..=values.len()).map(|i| format!("?{i}")).collect::<Vec<_>>().join(", ");
            let sql = format!("INSERT INTO {} ({columns}) VALUES ({marks})", quoted(R::TABLE));
            self.conn.execute(&sql, rusqlite::params_from_iter(values))?;
            record.set_id(self.conn.last_insert_rowid());
        } else {
            let sets = R::COLUMNS
                .iter()
                .enumerate()
                .map(|(i, c)| format!("{} = ?{}", quoted(c), i + 1))
                .collect::<Vec<_>>()
                .join(", ");
            let sql = format!("UPDATE {} SET {sets} WHERE \"id\" = ?{}", quoted(R::TABLE), values.len() + 1);
            let mut params = values;
            params.push(SqlValue::Integer(record.id()));
            let changed = self.conn.execute(&sql, rusqlite::params_from_iter(params))?;
            if changed == 0 {
                return Err(Error::NotFound {
                    table: R::TABLE,
                    id: Some(record.id()),
                });
            }
        }
        Ok(())
    }

    pub fn delete<R: Record>(&self, record: &R) -> Result<()> {
        let sql = format!("DELETE FROM {} WHERE \"id\" = ?1", quoted(R::TABLE));
        match self.conn.execute(&sql, [record.id()]) {
            Ok(_) => Ok(()),
            Err(rusqlite::Error::SqliteFailure(err, _)) if err.code == rusqlite::ErrorCode::ConstraintViolation => {
                Err(Error::InUse {
                    table: R::TABLE,
                    id: record.id(),
                })
            }
            Err(err) => Err(err.into()),
        }
    }

    fn select<R: Record>(&self, filter: &str, params: &[SqlValue]) -> Result<Vec<R>> {
        let sql = format!("SELECT {} FROM {}{filter}", select_columns::<R>(), quoted(R::TABLE));
        self.read(&sql, params)
    }

    /// The records a query finds, in its order.
    pub fn find<R: Record>(&self, query: &Query) -> Result<Vec<R>> {
        let (sql, params) = query.sql(R::TABLE, &select_columns::<R>());
        self.read(&sql, &params)
    }

    fn read<R: Record>(&self, sql: &str, params: &[SqlValue]) -> Result<Vec<R>> {
        let mut statement = self.conn.prepare(sql)?;
        let mut rows = statement.query(rusqlite::params_from_iter(params))?;
        let mut records = Vec::new();
        while let Some(row) = rows.next()? {
            let id: Id = row.get(0)?;
            let values = (1..=R::COLUMNS.len()).map(|i| row.get(i)).collect::<rusqlite::Result<Vec<SqlValue>>>()?;
            records.push(R::from_values(id, &values)?);
        }
        Ok(records)
    }

    /// Every stored record of an entity, in the order they were stored.
    pub fn all<R: Record>(&self) -> Result<Vec<R>> {
        self.select(" ORDER BY \"id\"", &[])
    }

    pub fn get<R: Record>(&self, id: Id) -> Result<R> {
        self.select::<R>(" WHERE \"id\" = ?1", &[SqlValue::Integer(id)])?
            .pop()
            .ok_or(Error::NotFound {
                table: R::TABLE,
                id: Some(id),
            })
    }

    /// The record a `ref` field points at.
    pub fn load<R: Record>(&self, id: Option<Id>) -> Result<R> {
        match id {
            Some(id) => self.get(id),
            None => Err(Error::NotFound { table: R::TABLE, id: None }),
        }
    }
}

/// A table or column name as SQL needs it, so names like `order` work.
pub fn quoted(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}

/// `"id"` and the stored columns of a record, for SELECT.
fn select_columns<R: Record>() -> String {
    std::iter::once("\"id\"".to_string())
        .chain(R::COLUMNS.iter().map(|c| quoted(c)))
        .collect::<Vec<_>>()
        .join(", ")
}
